      return `<div class="statblock"><h2>${icon('heart-crack')} ${esc(d.name)}</h2>${paras(d.desc)}<div class="give-row sticky-actions"><select id="condition-target" class="input">${targets.map(([v,n])=>`<option value="${esc(v)}">${esc(n)}</option>`).join('')}</select><button class="btn primary" data-action="compendium-condition" data-name="${esc(d.name)}">${icon('sparkles')} Aplicar condição</button></div></div>`;
